def next_batch_transport_pins(root):
    entries = {}
    for name,(length,checksum) in NEXT_BATCH_TRANSPORT_PINS.items():
        exact_pin(root,name,{'bytes':length,'sha256':checksum})
        entries[name] = {'file':name,'bytes':length,'sha256':checksum}
    return entries


def next_batch_envelope_inventory(root):
    for name in ('run-receipt.json','envelope-inventory-before-run.json'):
        length,checksum = NEXT_BATCH_TRANSPORT_PINS[name]
        exact_pin(root,name,{'bytes':length,'sha256':checksum})
    run = sealed(root / 'run-receipt.json',NEXT_BATCH_WF_SCHEMA + '.run-receipt')
    require(type(run['status']) is str and run['status'] == 'PASS','batch-parent-v4-successful-envelope')
    spec = ARTIFACTS['batch-parent-v4']
    require(canonical(run['launch']) == canonical({'run':spec['run'],'attempt':spec['attempt'],
        'head':spec['head'],'workflow':spec['workflow']}),'batch-parent-v4-original-v4-launch')
    before = read(root / 'envelope-inventory-before-run.json',True)
    names,dirs = inventory_fields(before)
    require(names == sorted(names) and dirs == sorted(dirs) and len(names) == 11646 and len(dirs) == 3525,
        'batch-parent-v4-original-complete-inventory-counts')
    excludes = ['envelope-inventory-before-run.json','run-receipt.json']
    require(canonical(run['envelope_payload_before_this_receipt']) == canonical({
        'bytes':1305760461,'directories':3525,'files':11646,'excludes':excludes,
        'inventory':{'file':excludes[0],'bytes':NEXT_BATCH_TRANSPORT_PINS[excludes[0]][0],
            'sha256':NEXT_BATCH_TRANSPORT_PINS[excludes[0]][1]}}),'batch-parent-v4-envelope-self-exclusion')
    require(sum(entry['bytes'] for entry in before['files']) == 1305760461 and
        set(excludes).isdisjoint(names),'batch-parent-v4-original-payload-bytes')
    files = copy.deepcopy(before['files'])
    files.extend({'file':name,'bytes':NEXT_BATCH_TRANSPORT_PINS[name][0],
        'sha256':NEXT_BATCH_TRANSPORT_PINS[name][1]} for name in excludes)
    files.sort(key=lambda item:item['file'])
    value = {'files':files,'directories':dirs}
    validate_inventory(value,{entry['file']:entry for entry in files},set(dirs))
    require(len(files) == 11648 and sum(item['bytes'] for item in files) == 1308094050,
        'batch-parent-v4-full-original-file-count-and-bytes')
    require(type(NEXT_BATCH_ROOT_REGISTRATION) is dict and
        sha(canonical(files)) == NEXT_BATCH_ROOT_REGISTRATION['files_sha256'] and
        sha(canonical(dirs)) == NEXT_BATCH_ROOT_REGISTRATION['directories_sha256'],
        'batch-parent-v4-root-complete-restored-list-registration')
    return value,run


def next_batch_inner_zip_read(root,inventory):
    names,dirs = inventory_fields(inventory)
    require(names == sorted(names) and dirs == sorted(dirs) and len(names) == 4747 and len(dirs) == 2330,
        'batch-parent-v4-inner-fixture-roster')
    files = {entry['file']:entry for entry in inventory['files']}
    expected_dirs,seen_files,seen_dirs,folded = set(dirs),set(),set(),set()
    total = 0
    with zipfile.ZipFile(root / 'selftest-fixtures.zip') as archive:
        infos = archive.infolist()
        require(len(infos) == 7077,'batch-parent-v4-inner-all-entry-count')
        for info in infos:
            directory = info.is_dir()
            name = safe_name(info.filename[:-1] if directory else info.filename)
            require(info.orig_filename == info.filename and name.split('/')[0] in ('P','C') and
                info.filename == name + ('/' if directory else '') and name.casefold() not in folded and
                not info.flag_bits & 1,'batch-parent-v4-inner-name-owner-and-unique')
            folded.add(name.casefold())
            kind = stat.S_IFMT((info.external_attr >> 16) & 0xffff)
            require(kind == (stat.S_IFDIR if directory else stat.S_IFREG),'batch-parent-v4-inner-exact-entry-type')
            require((directory and name in expected_dirs and info.file_size == 0) or
                (not directory and name in files and info.file_size == files[name]['bytes']),
                'batch-parent-v4-inner-registered-entry-and-size')
            checksum,size = hashlib.sha256(),0
            with archive.open(info) as stream:
                while True:
                    block = stream.read(1 << 20)
                    if not block:
                        break
                    size += len(block)
                    require(size <= info.file_size,'batch-parent-v4-inner-stream-size-bound')
                    checksum.update(block)
            require(size == info.file_size,'batch-parent-v4-inner-full-EOF-and-CRC')
            if directory:
                seen_dirs.add(name)
            else:
                require(checksum.hexdigest() == files[name]['sha256'],'batch-parent-v4-inner-whole-file-SHA')
                seen_files.add(name)
                total += size
    require(seen_files == set(files) and seen_dirs == expected_dirs,'batch-parent-v4-inner-exact-all-files-directories')
    return {'entries':7077,'files':len(files),'directories':len(dirs),'bytes':total,
        'every_entry_full_EOF_CRC_and_SHA':True,'ignored_entries':[]}


def restore_next_batch_parent_directories(root,extraction):
    # Authenticate every existing byte and every registered missing directory before the first mkdir.
    begun = time.monotonic()
    pins = next_batch_transport_pins(root)
    wanted,run = next_batch_envelope_inventory(root)
    before = scan(root)
    require(canonical(before['files']) == canonical(wanted['files']),
        'batch-parent-v4-all-11648-files-authenticated-before-directory-restoration')
    ancestors = set()
    for entry in wanted['files']:
        parent = PurePosixPath(entry['file']).parent
        while str(parent) != '.':
            ancestors.add(str(parent))
            parent = parent.parent
    require(type(extraction['entries']) is int and extraction['entries'] == 11648 and
        extraction['expanded_bytes'] == 1308094050 and extraction['full_EOF'] is True and
        len(ancestors) == 3487 and set(before['directories']) == ancestors,
        'batch-parent-v4-original-file-only-ZIP-and-3487-implicit-directories')
    missing = sorted(set(wanted['directories']) - ancestors)
    require(ancestors <= set(wanted['directories']) and missing == NEXT_BATCH_ABSENT_DIRECTORIES and len(missing) == 38,
        'batch-parent-v4-only-38-registered-missing-directories')
    controls = read(root / 'intake-controls-before.json',True)
    inventory_fields(controls)
    require(set(missing) <= set(controls['directories']),'batch-parent-v4-all-missing-directories-in-original-pre-P-controls')
    inventory = read(root / 'selftest-fixtures-inventory.json',True)
    projected = {'files':[dict(item,file=item['file'][18:]) for item in wanted['files']
        if item['file'].startswith('selftest-fixtures/')],
        'directories':[name[18:] for name in wanted['directories'] if name.startswith('selftest-fixtures/')]}
    require(canonical(projected) == canonical(inventory) and
        (root / 'selftest-fixtures-inventory.json').read_bytes() ==
        (root / 'selftest-fixtures-archive-readback.json').read_bytes() ==
        (root / 'selftest-fixtures-after-archive.json').read_bytes(),'batch-parent-v4-three-inner-inventories-and-envelope-projection')
    archived = sealed(root / 'selftest-fixtures-archive-receipt.json',NEXT_BATCH_WF_SCHEMA + '.selftest-fixture-archive')
    require(type(archived['status']) is str and archived['status'] == 'PASS' and archived['reason'] is None and
        archived['excluded_entries'] == [] and all(archived[key] is True for key in (
            'all_entries_and_explicit_directories_read','all_file_bytes_SHA_EOF_and_CRC_read',
            'both_completed_roots_unchanged','container_present','raw_fixtures_retained')) and
        all(archived[key] is False for key in ('archive_contains_itself','partial_or_missing_roots_claimed_complete',
            'silently_filtered_entries',*FALSE_ASSURANCE)),'batch-parent-v4-actual-complete-fixture-archive')
    for key,name in (('inventory','selftest-fixtures-inventory.json'),
            ('readback_inventory','selftest-fixtures-archive-readback.json'),
            ('after_inventory','selftest-fixtures-after-archive.json'),('archive','selftest-fixtures.zip')):
        require(canonical(archived[key]) == canonical(pins[name]) and
            canonical(run['selftest_fixture_archive_files'][name]) == canonical(pins[name]),
            'batch-parent-v4-archive-run-exact-file-pin:' + key)
    inner = next_batch_inner_zip_read(root,inventory)
    plan = sorted(missing,key=lambda name:(len(PurePosixPath(name).parts),name))
    planned,base = set(),root.resolve()
    for name in plan:
        target = root / safe_name(name)
        require(base in target.resolve().parents and not target.exists() and not target.is_symlink(),
            'batch-parent-v4-new-directory-contained-and-absent')
        parent = target.parent
        relative_parent = parent.relative_to(root).as_posix()
        require((parent.is_dir() and not parent.is_symlink()) or relative_parent in planned,
            'batch-parent-v4-all-directory-parents-planned-first')
        planned.add(name)
    save('batch-parent-v4-restoration-plan.json',seal(WF_SCHEMA,'batch-parent-v4-restoration-plan',{
        'artifact':ARTIFACTS['batch-parent-v4'],'root':str(base),'source_pins':pins,'original_files':11648,
        'original_directories':3487,'expected_directories':3525,'missing':plan,'inner_zip':inner,
        'all_file_bytes_authenticated_before_first_mkdir':True,'only_registered_missing_directories':True,
        'old_numerical_replays':0,**FALSE_ASSURANCE}))
    created = []
    try:
        for ordinal,name in enumerate(plan):
            target = root / name
            require(target.parent.is_dir() and not target.parent.is_symlink() and not target.exists() and
                not target.is_symlink(),'batch-parent-v4-directory-create-boundary')
            returned = os.mkdir(target)
            require(returned is None and target.is_dir() and not target.is_symlink() and
                target.resolve() == base.joinpath(*PurePosixPath(name).parts),
                'batch-parent-v4-directory-return-and-immediate-exists')
            row = {'ordinal':ordinal,'relative':name,'resolved_path':str(target.resolve()),
                'mkdir_return':None,'immediate_exists':True,'regular_directory':True}
            created.append(row)
            save('batch-parent-v4-restoration/' + str(ordinal).zfill(2) + '.json',row)
        after = scan(root)
        require(canonical(after) == canonical(wanted),'batch-parent-v4-full-reread-after-directory-restoration')
        require(canonical(scan(root / 'selftest-fixtures')) == canonical(inventory),
            'batch-parent-v4-full-fixture-reread-after-directory-restoration')
        status,reason = 'PASS',None
    except BaseException as exc:
        status,reason = 'FAIL',type(exc).__name__ + ':' + str(exc)
        raise
    finally:
        save('batch-parent-v4-restoration-result.json',seal(WF_SCHEMA,'batch-parent-v4-restoration-result',{
            'status':status,'reason':reason,'plan':pin(REPORT / 'batch-parent-v4-restoration-plan.json',
                'batch-parent-v4-restoration-plan.json'),'created':created,'created_count':len(created),
            'all_expected_files_and_directories_reread':status == 'PASS','elapsed_seconds':time.monotonic() - begun,
            'mathematical_replays':0,**FALSE_ASSURANCE}))
    return pin(REPORT / 'batch-parent-v4-restoration-result.json','batch-parent-v4-restoration-result.json')


def next_batch_registered_descriptor(root,name,expected_files):
    name = safe_name(name)
    require(name in expected_files,'batch-parent-v4-registered-file:' + name)
    expected = expected_files[name]
    require(canonical(pin(root / name,name)) == canonical(expected),'batch-parent-v4-actual-file-pin:' + name)
    return copy.deepcopy(expected)


def next_batch_saved_manifest(folder,suffix):
    value = sealed(folder / 'manifest.json',NEXT_BATCH_SCHEMA + '.' + suffix)
    require(value.get('eof',True) is True and type(value['files']) is list,'batch-parent-v4-manifest-full-EOF')
    names = []
    for entry in value['files']:
        require(type(entry) is dict and set(entry) in ({'file','bytes','sha256'},
            {'file','bytes','sha256','dtype','shape'}),'batch-parent-v4-manifest-descriptor-shape')
        name = safe_name(entry['file'])
        require('/' not in name and type(entry['bytes']) is int and entry['bytes'] >= 0 and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-parent-v4-manifest-descriptor-types')
        require(canonical(pin(folder / name,name)) == canonical({key:entry[key]
            for key in ('file','bytes','sha256')}),'batch-parent-v4-full-manifest-payload-hash')
        names.append(name)
    require(names == sorted(set(names)) and {p.name for p in folder.iterdir()} == {*names,'manifest.json'},
        'batch-parent-v4-manifest-full-directory-EOF')
    return value


def next_batch_fixed_reference(paths,anchor,descriptors):
    # Only the accepted batch fixed manifest is a reference-only document.
    name = 'output/fixed/manifest.json'
    batch_root,old_root = paths['batch-parent-v4'],paths['continuation']
    for root in (batch_root,old_root):
        for directory in (root,root / 'output',root / 'output/fixed'):
            require(directory.is_dir() and not directory.is_symlink() and
                (directory == root or root in directory.resolve().parents),
                'batch-fixed-reference-registered-directory')
    folder,old_folder = batch_root / 'output/fixed',old_root / 'output/fixed'
    value = sealed(folder / 'manifest.json',NEXT_BATCH_SCHEMA + '.fixed-manifest')
    require(set(value) == {'schema','sha256','owner_sha256','source_sha256','start_sha256',
        'accepted_fixed_manifest','accepted_geometry_stage_sha256','files',
        'fixed_values_independent_of_lambda'},'batch-fixed-reference-exact-nine-fields')
    reference_inventory = scan(folder)
    require(canonical(reference_inventory) == canonical({'files':[
        {'file':'manifest.json','bytes':descriptors['fixed']['bytes'],'sha256':descriptors['fixed']['sha256']}],
        'directories':[]}) and canonical(pin(folder / 'manifest.json',name)) == canonical(descriptors['fixed']),
        'batch-fixed-reference-manifest-only-full-roster')
    require(all(value[key + '_sha256'] == descriptors[key]['sha256'] for key in ('owner','source','start')),
        'batch-fixed-reference-original-batch-owner-source-start')
    require(type(value['accepted_fixed_manifest']) is dict and
        set(value['accepted_fixed_manifest']) == {'file','bytes','sha256'} and
        canonical(value['accepted_fixed_manifest']) == canonical(anchor['fixed']) and
        canonical(pin(old_folder / 'manifest.json',name)) == canonical(anchor['fixed']),
        'batch-fixed-reference-exact-registered-old64-manifest')
    old = sealed(old_folder / 'manifest.json',LOOP_SCHEMA + '.fixed-manifest')
    require(set(old) == {'schema','sha256','owner_sha256','source_sha256','scope',
        'accepted_geometry_stage_sha256','files','fixed_values_independent_of_lambda'},
        'batch-fixed-reference-old64-exact-eight-fields')
    for key in ('owner','source'):
        require(canonical(pin(old_root / anchor[key]['file'],anchor[key]['file'])) == canonical(anchor[key]) and
            old[key + '_sha256'] == anchor[key]['sha256'],'batch-fixed-reference-original-old64-owner-source')
    old_owner = sealed(old_root / anchor['owner']['file'],LOOP_SCHEMA + '.owner')
    require(canonical(old['scope']) == canonical(old_owner['scope']) and
        old['fixed_values_independent_of_lambda'] is True and value['fixed_values_independent_of_lambda'] is True,
        'batch-fixed-reference-old-scope-and-fixed-independence')
    geometry_path = paths['oracle'] / 'output/geometry/manifest.json'
    geometry = sealed(geometry_path,'d972.r07.section-cochain-oracle.v1.stage-manifest')
    geometry_pin = pin(geometry_path,'output/geometry/manifest.json')
    require(geometry['stage'] == 'geometry' and value['accepted_geometry_stage_sha256'] ==
        old['accepted_geometry_stage_sha256'] == geometry_pin['sha256'],
        'batch-fixed-reference-registered-geometry-provenance')
    names = ['basis.json','bfs-order.u32','canonical-index.json','carry.u8','chord-edges.u32',
        'chord-tau.u8','geometry.json','next-pos.u32','p1-exponent-residues.json','parent-edge.u32',
        'parent.u32','phi.u32','potential-tau.u8','prev-pos.u32','selected-chords.u32','tag-fox.json']
    json_names = {'basis.json','canonical-index.json','geometry.json','p1-exponent-residues.json','tag-fox.json'}
    require(type(old['files']) is list and len(old['files']) == 16 and
        type(value['files']) is list and len(value['files']) == 16,'batch-fixed-reference-sixteen-descriptors')
    projected,payload_pins = [],[]
    for expected,entry in zip(names,old['files'],strict=True):
        require(type(entry) is dict and set(entry) == {'file','bytes','sha256','dtype','shape'} and
            type(entry['file']) is str and entry['file'] == expected and safe_name(entry['file']) == expected and
            type(entry['sha256']) is str and HEX.fullmatch(entry['sha256']) is not None,
            'batch-fixed-reference-old-descriptor-name-order-and-types')
        ordinary(entry['bytes'],1)
        payload = {key:entry[key] for key in ('file','bytes','sha256')}
        if expected in json_names:
            require(type(entry['dtype']) is str and entry['dtype'] == 'json' and entry['shape'] is None,
                'batch-fixed-reference-json-five-key-to-three-key-projection')
            projected.append(payload)
        else:
            require(type(entry['dtype']) is str and entry['dtype'] in ('u8','u32le') and
                type(entry['shape']) is list and entry['shape'] and
                all(type(size) is int and size > 0 for size in entry['shape']),
                'batch-fixed-reference-binary-eleven-ordinary-shape')
            require(math.prod(entry['shape']) * {'u8':1,'u32le':4}[entry['dtype']] == entry['bytes'],
                'batch-fixed-reference-binary-shape-exact-byte-EOF')
            projected.append(entry)
        payload_pins.append(payload)
    require(canonical(value['files']) == canonical(projected),'batch-fixed-reference-all-typed-descriptor-projections')
    expected_inventory = {'files':sorted(payload_pins + [pin(old_folder / 'manifest.json','manifest.json')],
        key=lambda row:row['file']),'directories':[]}
    require(canonical(scan(old_folder)) == canonical(expected_inventory),
        'batch-fixed-reference-old64-all-sixteen-full-payload-hashes-and-directory-EOF')
    save('next-batch-fixed-reference-receipt.json',{'schema':WF_SCHEMA + '.fixed-reference-receipt.v1','status':'PASS',
        'reference':descriptors['fixed'],'accepted_fixed_manifest':anchor['fixed'],'geometry':geometry_pin,
        'reference_role':'batch-parent-v4','payload_role':'continuation','relative_directory':'output/fixed',
        'reference_inventory':reference_inventory,'payload_inventory':expected_inventory,
        'json_descriptors':5,'binary_descriptors':11,'payloads_copied_or_created':False,
        'source_executed_by_this_receipt':False,**FALSE_ASSURANCE})
    return value


def next_batch_fixture_history(root,run):
    archive = sealed(root / 'selftest-fixtures-archive-receipt.json',NEXT_BATCH_WF_SCHEMA + '.selftest-fixture-archive')
    require(canonical(run['selftest_fixture_archive_receipt']) ==
        canonical(pin(root / 'selftest-fixtures-archive-receipt.json','selftest-fixtures-archive-receipt.json')),
        'batch-parent-v4-run-archive-receipt-join')
    summaries = []
    for stage in ('before-producer','before-checker','after-checker'):
        descriptor = run['selftest_fixture_comparisons'][stage]
        payload_descriptor(root,descriptor)
        comparison = sealed(root / descriptor['file'],NEXT_BATCH_WF_SCHEMA + '.selftest-fixture-comparison')
        require(type(comparison['stage']) is str and comparison['stage'] == stage and
            comparison['status'] == 'PASS' and comparison['errors'] == comparison['missing'] == [] and
            [row['label'] for row in comparison['fixtures']] == ['producer-selftest','checker-selftest'],
            'batch-parent-v4-historical-complete-fixture-comparison')
        if stage == 'after-checker':
            require(canonical(archive['comparison']) == canonical(descriptor),'batch-parent-v4-archive-last-comparison')
        for row in comparison['fixtures']:
            label = row['label']
            require(row['present'] is True and row['unchanged'] is True and row['state'] == 'COMPLETE' and
                row['reason'] is None and row['root'] == run['selftest_fixture_roots'][label],
                'batch-parent-v4-historical-both-complete-roots')
            for key in ('baseline','inventory'):
                payload_descriptor(root,row[key])
            baseline = sealed(root / row['baseline']['file'],NEXT_BATCH_WF_SCHEMA + '.selftest-fixture-baseline')
            inventory = read(root / row['inventory']['file'],True)
            require(baseline['status'] == 'PASS' and baseline['label'] == label and baseline['root'] == row['root'] and
                canonical(baseline['inventory']) == canonical(inventory),
                'batch-parent-v4-historical-exact-baseline-inventory')
            actual = scan(root / 'selftest-fixtures' / ('P' if label == 'producer-selftest' else 'C'))
            require(canonical(actual) == canonical(inventory),'batch-parent-v4-restored-complete-fixture-subtree')
            for key in ('execution','selftest'):
                payload_descriptor(root,baseline[key])
            execution = sealed(root / baseline['execution']['file'],NEXT_BATCH_WF_SCHEMA + '.execution-result')
            test = sealed(root / baseline['selftest']['file'],NEXT_BATCH_SCHEMA + '.selftest')
            require(execution['label'] == label and type(execution['exit_code']) is int and execution['exit_code'] == 0 and
                execution['outer_terminated'] is False and test['status'] == 'PASS',
                'batch-parent-v4-actual-historical-selftest-receipts-without-rerun')
        summaries.append({'stage':stage,'receipt':descriptor,'both_complete_roots_unchanged':True})
    return summaries


def authenticate_next_batch_parent(paths,inventories,anchor,code,batch_anchor):
    root = paths['batch-parent-v4']
    registered,run = next_batch_envelope_inventory(root)
    require(canonical(inventories['batch-parent-v4']) == canonical(registered),
        'batch-parent-v4-whole-restored-registered-inventory')
    require(sha(canonical(registered['files'])) == NEXT_BATCH_ROOT_REGISTRATION['files_sha256'] and
        sha(canonical(registered['directories'])) == NEXT_BATCH_ROOT_REGISTRATION['directories_sha256'],
        'batch-parent-v4-public-whole-inventory-list-hashes')
    expected = {item['file']:item for item in registered['files']}
    descriptors = {key:next_batch_registered_descriptor(root,name,expected) for key,name in NEXT_BATCH_FIELDS.items()}
    layout = sealed(root / NEXT_BATCH_FIELDS['parent_layout'],NEXT_BATCH_SCHEMA + '.parent-layout')
    old_parents = [{'role':role,'artifact':ARTIFACTS[role],**inventories[role]} for role in PREVIOUS_ROLES]
    require(canonical(layout['parents']) == canonical(old_parents) and canonical(layout['anchor']) == canonical(anchor) and
        canonical(layout['runtime']) == canonical(runtime()) and canonical(layout['registration']) == canonical(REGISTRATION) and
        canonical(layout['batch_anchor']) == canonical(batch_anchor),
        'batch-parent-v4-original-sixteen-parents-both-old-anchors-and-runtime')
    for key in ('producer_dependencies','checker_dependencies','data'):
        require(canonical(layout['code'][key]) == canonical(code[key]),'batch-parent-v4-retained-code-list:' + key)
    original_code = layout['code']
    require(canonical(original_code['producer']) == canonical({'file':'search/d972_r07_fixed_lambda_cycle_batch_v4.py',
        'bytes':290457,'sha256':'a58f7c116558fdc430025a9e095d29d0b04e0f20c9295264fca58a4c13510d0a'}) and
        canonical(original_code['checker']) == canonical({'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v4.py',
        'bytes':261170,'sha256':'a29380ec00876225cc618c7025d671a3da79aea3b31b829dedba13c59ba84633'}),
        'batch-parent-v4-original-P4-C4-not-renamed-to-current')
    old_acceptance = read(root / 'acceptance.json',True)
    expected_portable = {'schema':NEXT_BATCH_SCHEMA + '.acceptance','parents':old_parents,'anchor':anchor,
        'batch_anchor':batch_anchor,'code':original_code,'runtime':runtime(),'registration':REGISTRATION}
    require(type(old_acceptance) is dict and set(old_acceptance) == set(expected_portable) and
        canonical(portable_acceptance(old_acceptance)) == canonical(expected_portable),
        'batch-parent-v4-original-seven-key-acceptance-and-sixteen-root-projection')
    for parent in old_acceptance['parents']:
        require(type(parent) is dict and set(parent) == {'role','path','artifact','files','directories'} and
            type(parent['path']) is str and Path(parent['path']).is_absolute(),
            'batch-parent-v4-historical-host-roots-kept-in-original-acceptance')
    require(set(layout) == {'schema','sha256','parents','anchor','batch_anchor','code','runtime','registration',
        'portable_acceptance_sha256'} and layout['portable_acceptance_sha256'] == sha(canonical(expected_portable)),
        'batch-parent-v4-complete-original-layout-seal-and-portable-sha')
    owner = sealed(root / NEXT_BATCH_FIELDS['owner'],NEXT_BATCH_SCHEMA + '.owner')
    source = sealed(root / NEXT_BATCH_FIELDS['source'],NEXT_BATCH_SCHEMA + '.source')
    require(owner['parent_layout_sha256'] == descriptors['parent_layout']['sha256'] and
        owner['portable_acceptance_sha256'] == layout['portable_acceptance_sha256'] and
        owner['source_sha256'] == descriptors['source']['sha256'] and
        canonical(owner['registration']) == canonical(REGISTRATION) and
        canonical(source['producer']) == canonical(original_code['producer']) and
        canonical(source['checker']) == canonical(original_code['checker']) and
        canonical(source['retained_producer_dependencies']) == canonical(P_DEPS) and
        canonical(source['retained_checker_dependencies']) == canonical(C_DEPS) and
        canonical(source['data']) == canonical(DATA) and canonical(source['runtime']) == canonical(runtime()),
        'batch-parent-v4-original-owner-source-runtime-and-retained-closure')
    previous_separator = sealed(paths['batch-parent'] / BATCH_FIELDS['separator'],BATCH_SCHEMA + '.separator')
    original_start = sealed(root / NEXT_BATCH_FIELDS['start'],NEXT_BATCH_SCHEMA + '.start')
    require(canonical(original_start['accepted_target_derivation_parents']) ==
        canonical(previous_separator['lambda_rho2']['accepted_target_derivation_parents']),
        'batch-parent-v4-full225-ancestry-identical-to-v3-final-including-zero-scalars')
    old_intake = sealed(root / NEXT_BATCH_FIELDS['parent_intake'],NEXT_BATCH_SCHEMA + '.parent-intake')
    require(canonical({key:old_intake[key] for key in ('accepted_batch_anchor_sha256','accepted_batch_head_sha256',
        'accepted_batch_result_sha256','accepted_batch_checker_sha256','upstream_completed_steps','accepted_parent_batch_rows',
        'old_rank','rank','generation','old_target_derivation_parents','target_derivation_parents',
        'candidate_manifests_checked','row_manifests_checked','candidate_phase_manifests_checked','checkpoints_checked',
        'invocations_checked')}) == canonical({'accepted_batch_anchor_sha256':sha(canonical(batch_anchor)),
            'accepted_batch_head_sha256':batch_anchor['head']['sha256'],
            'accepted_batch_result_sha256':batch_anchor['result']['sha256'],
            'accepted_batch_checker_sha256':batch_anchor['checker']['sha256'],'upstream_completed_steps':64,
            'accepted_parent_batch_rows':128,'old_rank':1450,'rank':1578,'generation':8283,
            'old_target_derivation_parents':97,'target_derivation_parents':225,'candidate_manifests_checked':128,
            'row_manifests_checked':128,'candidate_phase_manifests_checked':768,'checkpoints_checked':772,
            'invocations_checked':1}) and original_start['parent_intake_sha256'] == descriptors['parent_intake']['sha256'],
        'batch-parent-v4-original1450-to1578-intake-is-not-a1706-result')
    require(canonical(run['accepted_batch_anchor']) == canonical(batch_anchor) and
        canonical(run['accepted_artifacts']) == canonical({role:ARTIFACTS[role] for role in PREVIOUS_ROLES}),
        'batch-parent-v4-run-original-batch-anchor-and-sixteen-artifacts')
    receipt = sealed(root / 'source-receipt.json',NEXT_BATCH_WF_SCHEMA + '.source-receipt')
    require(receipt['status'] == 'PASS' and canonical(receipt['code']) == canonical(original_code) and
        canonical(receipt['runtime']) == canonical(runtime()) and canonical(receipt['launch']) == canonical(run['launch']),
        'batch-parent-v4-original-source-receipt-code-runtime-launch')
    for entry in receipt['files']:
        exact_pin(root,'checkout-sources/' + safe_name(entry['file']),{key:entry[key] for key in ('bytes','sha256')})
    require(len(receipt['files']) == 24 and canonical(receipt['files']) == canonical(code_union(original_code)),
        'batch-parent-v4-all24-original-source-and-raw-bytes')
    head = sealed(root / NEXT_BATCH_FIELDS['head'],NEXT_BATCH_SCHEMA + '.head')
    result = sealed(root / NEXT_BATCH_FIELDS['result'],NEXT_BATCH_SCHEMA + '.result')
    checked = sealed(root / NEXT_BATCH_FIELDS['checker'],NEXT_BATCH_SCHEMA + '.checker-result')
