    require(canonical(layout['parents']) == canonical(old_parents) and canonical(layout['anchor']) == canonical(anchor) and
        canonical(layout['runtime']) == canonical(runtime()) and canonical(layout['registration']) == canonical(REGISTRATION) and
        canonical(layout['batch_anchor']) == canonical(batch_anchor) and canonical(layout['next_batch_anchor']) == canonical(next_batch_anchor) and
        canonical(layout['batch_anchor_v5']) == canonical(batch_anchor_v5) and
        canonical(layout['batch_anchor_v6']) == canonical(batch_anchor_v6),
        'batch-parent-v7-original-nineteen-parents-all-four-old-anchors-and-runtime')
    for key in ('producer_dependencies','checker_dependencies','data'):
        require(canonical(layout['code'][key]) == canonical(code[key]),'batch-parent-v7-retained-code-list:' + key)
    original_code = layout['code']
    require(canonical(original_code['producer']) == canonical({'file':'search/d972_r07_fixed_lambda_cycle_batch_v7_repair_v2.py',
        'bytes':552885,'sha256':'6fe3ee03967b21d030a3bf141001df58305306c3b934b1c3fb71bd08a1a419bb'}) and
        canonical(original_code['checker']) == canonical({'file':'search/check_d972_r07_fixed_lambda_cycle_batch_v7_repair_v2.py',
        'bytes':525707,'sha256':'d0e789ae15978023f29dcfcf21d4d2c4ac7100f9d8241351bee5b2d889132607'}),
        'batch-parent-v7-original-P7-C7-not-renamed-to-current')
