def v8_c_seventh_values():
    def expand(value,variables):
        if type(value) is list:
            return [expand(item,variables) for item in value]
        if type(value) is not dict:
            return value
        operations = [key for key in value if key.startswith('$')]
        if not operations:
            return {key:expand(item,variables) for key,item in value.items()}
        require(len(value) == len(operations) == 1,'C-seventh-single-reserved-expression')
        operation = operations[0];item = value[operation]
        if operation == '$var':
            return variables[item]
        if operation == '$decimal':
            result = expand(item,variables);ordinary(result,0)
            return str(result)
        if operation == '$concat':
            parts = expand(item,variables);require(all(type(part) is str for part in parts),'C-seventh-string-parts')
            return ''.join(parts)
        require(operation == '$mod','C-seventh-finite-expression-domain')
        left,right = expand(item,variables);ordinary(left,0);ordinary(right,1)
        return left % right
    values = {}
    for name,row in C_SEVENTH_SERIALIZER['value_definitions'].items():
        if row['kind'] == 'literal':
            value = copy.deepcopy(row['value'])
        elif row['kind'] == 'seal':
            value = v7_sixth_seal(copy.deepcopy(row['unsigned_value']))
        else:
            require(row['kind'] == 'array_template','C-seventh-finite-definition-kind')
            value = []
            for part in row['parts']:
                ordinary(part['start'],0,737);ordinary(part['stop'],part['start'],737);ordinary(part['step'],1,737)
                value.extend(expand(part['item'],{part['index']:index}) for index in range(part['start'],part['stop'],part['step']))
            require(len(value) == row['length'],'C-seventh-complete737-template-length')
        values[name] = value
